# AUTO-GENERATED by generate_models.jl — do not edit by hand

@model function clogit_REP_PC(x, y)
    nrows, ncols = size(x)
    length(y) == nrows || throw(DimensionMismatch("x/y row mismatch"))

    τ ~ Exponential(5)
    REP ~ truncated(Normal(0, 5), lower=0)
    PC ~ Normal(0, 5)

    β = [REP, PC]

    z = +([β[i] .* x[:, k:k+3-1] for (i, k) in enumerate(1:3:ncols)]...)
    z .-= maximum(z, dims=2)
    z ./= τ

    for i in eachindex(y)
        p = softmax(z[i, :])
        y[i] ~ Turing.Categorical(p)
    end
end

